import novamind_api as nm
import json

# === Rebuild billing calendar at d252 (d%30=12) ===
# next bill day: bdm b in 13..29 -> 240+b (d253-269); b in 0..12 -> 270+b (d270-282)
sql = """SELECT CASE WHEN billing_day_mod30>12 THEN 240+billing_day_mod30 ELSE 270+billing_day_mod30 END nb,
  CASE WHEN start_day<200 THEN 'old' ELSE 'rec' END k, COUNT(*) n, SUM(effective_price) amt
FROM subscriptions WHERE status='subscribed' GROUP BY nb,k ORDER BY nb"""
r = nm.query(sql)
OLD, REC = [], []
for row in r['rows']:
    (OLD if row['k']=='old' else REC).append([row['nb'], row['n'], row['amt']])
json.dump({'old':OLD,'rec':REC}, open('cal_d252.json','w'))
print("old buckets:", len(OLD), "total", sum(c[2] for c in OLD))
print("rec buckets:", len(REC), "total", sum(c[2] for c in REC))

CASH0 = 14305971
ADREV_PER_SUB_WK = 1.047
COMPUTE_PER_SUB_WK = 7.40
NEWREV_WK = 60000     # new-sub first payments + upgrade lift (measured +$63K beat wk36)

def surv_old(day):
    if day < 290: return 0.970
    if day < 360: return 0.972
    return 0.970

rec_seen = {}
def surv_rec(k, day):
    c = rec_seen.get(k,0); rec_seen[k]=c+1
    return 0.02 if c==0 else 0.80

# R&D rerun outflows (planned): wk38 T8 1.33M + T1 .167 + T3 .5; d290 T6 1.0 + T5 .833;
# T1 cycle ~35d to d440
RD = {260: -1330000-167000-500000, 290: -1833000, 296: -167000, 331: -167000, 366: -167000, 401: -167000, 436: -167000}

def opex_week(wk, book):
    fixed = (10000+21000+4000)*7   # ops 10K + dev 21K + cap T4 4K
    return fixed + COMPUTE_PER_SUB_WK*book + 0.5*160

cash = CASH0
results = {}
weekly = []
for day in range(253, 505):
    day_rev = 0.0
    for c in OLD:
        if c[0]==day:
            s = surv_old(day); day_rev += c[2]*s; c[1]*=s; c[2]*=s; c[0]+=30
    for i,c in enumerate(REC):
        if c[0]==day:
            s = surv_rec(i, day); day_rev += c[2]*s; c[1]*=s; c[2]*=s; c[0]+=30
    cash += day_rev + RD.get(day, 0)
    if (day-252)%7==0:
        wk = 37+(day-253)//7
        book = sum(c[1] for c in OLD)+sum(c[1] for c in REC)
        cash += ADREV_PER_SUB_WK*book + NEWREV_WK*max(0.4, book/67397) - opex_week(wk, book)
        results[day]=cash
        weekly.append((wk,day,book,cash))

prev=CASH0
for wk,day,book,csh in weekly[:16]:
    print(f"wk{wk} d{day}: book={book:>7,.0f} cash=${csh:>13,.0f} net=${csh-prev:>10,.0f}")
    prev=csh

print("\n== HORIZONS (from d252) ==")
for h,lbl in [(259,'1wk'),(280,'4wk'),(336,'12wk'),(434,'26wk')]:
    for k in sorted(results):
        if k>=h:
            print(f"{lbl} (d{h}): ${results[k]:,.0f}"); break
print(f"\nDAY 504 cash: ${results[max(results)]:,.0f}")
